def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The large monochrome 3x3 squares are the line-emitting objects.
    objects = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
    # Each square draws a full horizontal and vertical line through its center.
    # Where unlike lines intersect, leave the collision cell blank.
    lines = {}
    for r, c, color in objects:
        for cc in range(w):
            lines.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            lines.setdefault((rr, c), set()).add(color)
    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
